// Input: items[0].json הוא או אובייקט תוצאה או מערך בגודל 1 עם התוצאה
const res = Array.isArray(items[0].json) ? items[0].json[0] : items[0].json;

// הגנה בסיסית
const segs = Array.isArray(res.segments) ? res.segments : [];

// --- איחוד סגמנטים רצופים של אותו דובר (מפחית “רעש” ב-SRT) ---
function mergeConsecutiveBySpeaker(segments) {
  const out = [];
  for (const s of segments) {
    if (!out.length) { out.push({...s}); continue; }
    const last = out[out.length - 1];
    if (last.speaker === s.speaker && (s.start - last.end) <= 0.6) {
      last.text = (last.text + " " + (s.text || "")).trim();
      last.end = s.end ?? last.end;
    } else {
      out.push({...s});
    }
  }
  return out;
}
const merged = mergeConsecutiveBySpeaker(segs);

// --- כלים ---
function toSrtTime(t) {
  if (typeof t !== 'number' || isNaN(t)) t = 0;
  const ms = Math.floor((t % 1) * 1000);
  const s = Math.floor(t) % 60;
  const m = Math.floor(t / 60) % 60;
  const h = Math.floor(t / 3600);
  const pad = n => String(n).padStart(2, '0');
  return `${pad(h)}:${pad(m)}:${pad(s)},${String(ms).padStart(3,'0')}`;
}

// מסכת ספרות ארוכות (PII בסיסי)
function maskDigits(txt) {
  return String(txt).replace(/\d{4,}/g, m => m.replace(/\d/g, '•'));
}

// --- בניית SRT דיאריזציה ---
let idx = 1;
let srt = '';
for (const s of merged) {
  const start = toSrtTime(s.start ?? 0);
  const end   = toSrtTime(s.end ?? ((s.start ?? 0) + 2));
  const spk   = s.speaker || 'SPK';
  const line  = maskDigits((s.text || '').trim());
  srt += `${idx++}\n${start} --> ${end}\n${spk}: ${line}\n\n`;
}

// --- JSON “נקי” לדיאריזציה ---
const cleanJson = {
  text: res.text || '',
  segments: merged.map(s => ({
    speaker: s.speaker || 'SPK',
    start: s.start ?? null,
    end: s.end ?? null,
    text: s.text ?? ''
  })),
  usage: res.usage || null,
};

// --- Plain transcript (ללא דוברים) ---
const plainTextRaw = res.text && typeof res.text === 'string'
  ? res.text
  : segs.map(s => s.text || '').join(' ').trim();

const plainText = maskDigits(plainTextRaw);

// --- שמות קבצים ---
const origName = (items[1] && items[1].json.originalFileName) || 'audio';

// הסר את הסיומת (.wav, .mp3 וכו')
const base = origName.replace(/\.[^.]+$/, '');

// צור timestamp קצר וקריא: 2025-10-30_13-35
const now = new Date();
const stamp = now.toISOString().slice(0,16).replace('T', '_').replace(/:/g, '-');

// שמות הקבצים עם השם המקורי + timestamp
const srtName   = `${base}_${stamp}.srt`;
const jsonName  = `${base}_${stamp}.json`;
const txtName   = `${base}_${stamp}.txt`;


// --- קבצי בינארי ---
const srtBuf  = Buffer.from(srt, 'utf8');
const jsonBuf = Buffer.from(JSON.stringify(cleanJson, null, 2), 'utf8');
const BOM = '\uFEFF';
const txtBuf  = Buffer.from(BOM + plainText, 'utf8');

return [{
  json: {
    summary: {
      diarized_segments: merged.length,
      plain_length_chars: plainText.length
    },
    // ✅ רק השורה הזו חדשה:
    segments: merged
  },
  binary: {
    srt:  { data: srtBuf.toString('base64'),  fileName: srtName,  mimeType: 'application/x-subrip' },
    json: { data: jsonBuf.toString('base64'), fileName: jsonName, mimeType: 'application/json' },
    txt:  { data: txtBuf.toString('base64'),  fileName: txtName,  mimeType: 'text/plain; charset=utf-8' }
  }
}];

// שמור את השם המקורי גם ב-json וגם ב-binary metadata
const originalName = $input.item.json.body?.fileName || $input.item.json.fileName || 'audio';
// הוסף את השם ל-binary metadata (כדי שיעבור דרך OpenAI)
if ($input.item.binary && $input.item.binary.data0) {
  $input.item.binary.data0.originalFileName = originalName;
}

// גם ב-json
$input.item.json.originalFileName = originalName;

return $input.item;

